#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Run from anywhere: paths below are from the repo root. FROM=n starts at stage n on a re-run.
cd "$(git rev-parse --show-toplevel)"
# The Maker's CLOUDFLARE_API_KEY and E2B_API_KEY are offered from here (Enter keeps them). Nothing is written to it.
ENV_FILE=apps/maker/.env
ACCOUNT=51a5a41f7bd8425703a6f1d92f867f4d
export CLOUDFLARE_ACCOUNT_ID=$ACCOUNT
CF_WORKERS=https://dash.cloudflare.com/$ACCOUNT/workers-and-pages
REPO=chengchao/hopon
REQUIRED_SECRETS=(CLERK_JWT_KEY CLERK_SECRET_KEY OPERATOR_PASSWORD OPERATOR_WEBHOOK_URL CLOUDFLARE_API_KEY E2B_API_KEY PREVIEW_SECRET)
WORKER_SECRETS=() # "<Worker> <NAME>" set this run
TOTAL_STAGES=9

# run_stage "Name" fn: shows the stage, then runs fn unless FROM skips past it.
run_stage() {
  stage "$1"
  if (( _STAGE_INDEX < ${FROM:-1} )); then note "skipped (FROM=${FROM})"; return; fi
  "$2"
}
# stop "why" ends the wizard so you can fix it and re-run from this stage.
stop() {
  warn "$1"
  warn "Then re-run: FROM=$_STAGE_INDEX scripts/deploy-setup.sh"
  exit 1
}
# wr runs the repo's wrangler in apps/worker, so it reads apps/worker/wrangler.jsonc. Its stdin is never a terminal,
# so it never offers to edit that file.
wr() { pnpm --silent -F worker exec wrangler "$@"; }
# ENV below is "" for the hopon Worker, or "preview" for hopon's Preview base config: the secrets each new Preview of
# hopon starts with.
worker_name() { [[ "$1" == preview ]] && printf "hopon's Previews" || printf 'hopon'; }
# secret_names ENV lists the secrets that Worker already has (none if it doesn't exist yet).
secret_names() {
  if [[ "$1" == preview ]]; then
    wr preview base-config secret list --json </dev/null 2>/dev/null
  else
    wr secret list </dev/null 2>/dev/null
  fi | grep -oE '"name": *"[A-Z0-9_]+"' | grep -oE '[A-Z0-9_]+"$' | tr -d '"' || true
}
# put_secret ENV NAME < value: a secret on that Worker, or on the Preview base config.
put_secret() {
  if [[ "$1" == preview ]]; then
    wr preview base-config secret put "$2" >/dev/null || stop "wrangler preview base-config secret put $2 failed."
  else
    wr secret put "$2" >/dev/null || stop "wrangler secret put $2 failed."
  fi
  WORKER_SECRETS+=("$(worker_name "$1") $2")
  printf '  %s✓ set%s %s on %s\n' "$GREEN" "$RESET" "$2" "$(worker_name "$1")"
}
# clerk_page ENV: where that Worker's Clerk keys are. Previews use the Development instance, like local dev.
clerk_page() {
  open_url "https://dashboard.clerk.com/last-active?path=api-keys"
  if [[ -n "$1" ]]; then
    step "Switch to the hopon app's Development instance (top left), on API keys."
  else
    step "Switch to the hopon app's Production instance (top left), on API keys."
  fi
}
# set_worker_secrets ENV walks every secret in secrets.required for that Worker. One it already has is kept unless
# you say to replace it.
set_worker_secrets() {
  local env="$1" worker have name value pem
  worker=$(worker_name "$env")
  have=$(secret_names "$env")
  for name in "${REQUIRED_SECRETS[@]}"; do
    printf '\n'
    if grep -qx "$name" <<<"$have" && ! confirm "$worker already has $name. Replace it?"; then
      note "kept $name"
      continue
    fi
    case "$name" in
      CLERK_JWT_KEY)
        clerk_page "$env"
        step "Show the JWT public key, copy the PEM and save it to a file (it is a public key)."
        ask pem "Path to the PEM file:"
        pem=${pem/#\~/$HOME}
        [[ -f "$pem" ]] || stop "No file at $pem."
        put_secret "$env" CLERK_JWT_KEY <"$pem"
        continue
        ;;
      CLERK_SECRET_KEY)
        clerk_page "$env"
        step "Copy the Secret key (sk_test_… for Previews, sk_live_… for production)."
        ask_secret CLERK_SECRET_KEY "Paste the Clerk secret key:"
        value=$CLERK_SECRET_KEY
        ;;
      OPERATOR_PASSWORD)
        step "Make a new password of at least 32 random characters in your password manager, saved as"
        step "\"hopon $worker /operator\". You log in to $worker's /operator page with it."
        ask_secret OPERATOR_PASSWORD "Paste the password:"
        value=$OPERATOR_PASSWORD
        ;;
      OPERATOR_WEBHOOK_URL)
        step "The webhook every new Report is POSTed to (README step 5). Previews can use a test one."
        ask_secret OPERATOR_WEBHOOK_URL "Paste the webhook URL:"
        value=$OPERATOR_WEBHOOK_URL
        ;;
      CLOUDFLARE_API_KEY)
        step "modelFetch's Cloudflare token (AI Gateway Run + Workers AI), the one in $ENV_FILE."
        ask_secret CLOUDFLARE_API_KEY "Paste the token:"
        value=$CLOUDFLARE_API_KEY
        ;;
      E2B_API_KEY)
        step "The E2B key (https://e2b.dev/dashboard?tab=keys), the one in $ENV_FILE. Only the Coder gets it."
        ask_secret E2B_API_KEY "Paste the E2B key:"
        value=$E2B_API_KEY
        ;;
      PREVIEW_SECRET)
        note "Signs Draft preview links: a fresh random one, never shown."
        value=$(openssl rand -base64 32)
        ;;
    esac
    [[ -n "$value" ]] || stop "$name is empty."
    put_secret "$env" "$name" < <(printf '%s' "$value")
  done
}

banner "Deploys: GitHub Actions for production and Previews"

stage_start() {
  say "The Deploy workflow deploys the hopon Worker from main and a Preview of it from every other branch, with the"
  say "scripts in apps/worker/package.json. There's no staging: merging a PR is going live. This sets it up, once."
  local tool
  for tool in git gh pnpm openssl; do
    command -v "$tool" >/dev/null 2>&1 || stop "Install $tool first."
  done
  gh auth status >/dev/null 2>&1 || stop "Log in to GitHub: gh auth login"
  if ! grep -q "$ACCOUNT" < <(wr whoami </dev/null 2>/dev/null); then
    step "Log in to Cloudflare as the account that owns hopon ($ACCOUNT)."
    wr login
  fi
  git fetch -q origin
  grep -q '"deploy:preview"' < <(git show origin/main:apps/worker/package.json) ||
    stop "origin/main has no deploy:preview yet. Merge the Previews PR first: the deploys run the branch's scripts."
  printf '  %s✓%s logged in, and main has the deploy scripts\n' "$GREEN" "$RESET"
  pause
}
run_stage "Before you start" stage_start

stage_preview_resources() {
  say "Every Preview shares one D1 database and one R2 bucket, both named hopon-staging (the previews block in"
  say "apps/worker/wrangler.jsonc)."
  if wr d1 info hopon-staging </dev/null >/dev/null 2>&1; then
    note "D1 hopon-staging exists"
  elif confirm "Create D1 database hopon-staging?"; then
    wr d1 create hopon-staging </dev/null >/dev/null || stop "wrangler d1 create failed."
    printf '  %s✓ created%s D1 hopon-staging\n' "$GREEN" "$RESET"
    warn "Put its id (wrangler d1 info hopon-staging) in previews.d1_databases in apps/worker/wrangler.jsonc and in"
    warn "apps/worker/wrangler.preview-migrations.jsonc, and merge that to main."
  else
    stop "The Previews need it."
  fi
  if wr r2 bucket info hopon-staging </dev/null >/dev/null 2>&1; then
    note "R2 hopon-staging exists"
  elif confirm "Create R2 bucket hopon-staging?"; then
    wr r2 bucket create hopon-staging </dev/null >/dev/null || stop "wrangler r2 bucket create failed."
    printf '  %s✓ created%s R2 hopon-staging\n' "$GREEN" "$RESET"
  else
    stop "The Previews need it."
  fi
  pause
}
run_stage "The Previews' D1 and R2" stage_preview_resources

stage_production_secrets() {
  say "hopon's runtime secrets. It already has the older ones; the Maker adds CLOUDFLARE_API_KEY, E2B_API_KEY"
  say "and PREVIEW_SECRET."
  set_worker_secrets ""
  pause
}
run_stage "Production Worker secrets" stage_production_secrets

stage_games_to_r2() {
  say "The first production deploy applies *_games_are_files.sql (#145), which drops every published Game's HTML"
  say "from D1. The deploy copies that HTML to R2 bucket hopon first (games-to-r2 --remote, which does nothing once"
  say "D1 is past the migration), so the bucket has to exist."
  if wr r2 bucket info hopon </dev/null >/dev/null 2>&1; then
    note "R2 hopon exists"
  elif confirm "Create R2 bucket hopon?"; then
    wr r2 bucket create hopon </dev/null >/dev/null || stop "wrangler r2 bucket create failed."
    printf '  %s✓ created%s R2 hopon\n' "$GREEN" "$RESET"
  else
    stop "Production's deploy needs it."
  fi
  pause
}
run_stage "R2 for published Games, before production migrates" stage_games_to_r2

stage_deploy_secrets() {
  say "The Deploy workflow (.github/workflows/deploy.yml) deploys with two repository secrets. Make its Cloudflare"
  say "token now:"
  open_url "https://dash.cloudflare.com/profile/api-tokens"
  step "Create Token → Custom token, named \"hopon deploys (GitHub Actions)\", for account $ACCOUNT, with Account →"
  step "Workers Scripts, D1, Containers and Workers R2 Storage → Edit, and Account Settings → Read. Don't reuse the"
  step "model key: it can't edit Workers Scripts, so wrangler gets \"No access to the specified resource\"."
  ask_secret CLOUDFLARE_API_TOKEN "Paste the token:"
  [[ -n "$CLOUDFLARE_API_TOKEN" ]] || stop "CLOUDFLARE_API_TOKEN is empty."
  set_secret CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
  ask_secret E2B_API_KEY "Paste the E2B key, for the template build (Enter keeps $ENV_FILE's):"
  [[ -n "$E2B_API_KEY" ]] || stop "E2B_API_KEY is empty."
  set_secret E2B_API_KEY "$E2B_API_KEY"
  open_url "$CF_WORKERS"
  step "Open hopon → Settings → Build. If it shows a connected Git repository, Disconnect it: Workers Builds has no"
  step "Docker, so its deploy of main would migrate D1 and then fail."
  pause "Disconnected, or never connected?"
}
run_stage "Deploy secrets" stage_deploy_secrets

stage_previews() {
  say "Every other branch (each PR) gets a Worker Preview of hopon: its own URL, Talker, Coder and container,"
  say "on hopon-staging's D1 and R2 (the previews block in apps/worker/wrangler.jsonc)."
  say "A Preview inherits none of hopon's secrets: each starts from the Preview base config's. Changing one later"
  say "reaches only Previews created after it (wrangler preview secret put NAME --name <preview> fixes one)."
  set_worker_secrets preview
  pause
}
run_stage "Worker Previews of hopon" stage_previews

stage_protect_main() {
  say "A push to main deploys without waiting for GitHub checks, so main only takes commits that passed them: PRs"
  say "into main need the Check and Commit messages workflows green and up to date with main."
  if confirm "Protect main on $REPO with those required checks?"; then
    gh api -X PUT "repos/$REPO/branches/main/protection" --input - >/dev/null <<'JSON' || stop "gh api failed."
{
  "required_status_checks": { "strict": true, "checks": [{ "context": "check" }, { "context": "commitlint" }] },
  "enforce_admins": false,
  "required_pull_request_reviews": null,
  "restrictions": null
}
JSON
    printf '  %s✓ protected%s main\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("branch protection on main (Settings → Branches)")
  fi
  pause
}
run_stage "Protect main" stage_protect_main

stage_first_deploy() {
  say "Open a PR: its Preview deploys on the push. The first run makes the hopon-maker-preview E2B template from"
  say "scratch, so it takes a few minutes."
  open_url "https://github.com/$REPO/actions/workflows/deploy.yml"
  step "Wait for the PR's Deploy run to go green; its log has the Preview's URL."
  step "Point a dev build of the app at it: EXPO_PUBLIC_API_URL=https://<branch>-hopon.<subdomain>.workers.dev"
  step "with the Clerk Development publishable key, and make a game in a new Draft."
  step "Once, check a deploy mid-build: while a build runs, push to the PR. The turn should still finish."
  pause "The PR's Preview checked?"
  say "Merging it deploys production: it copies published Games' HTML to R2, runs production's migrations (with"
  say "*_games_are_files.sql) and deploys the hopon Worker."
  step "Merge the PR, then watch main's Deploy run until it's green."
  pause
}
run_stage "A PR's Preview, then production" stage_first_deploy

finish
(( ${#WORKER_SECRETS[@]} )) && note "set Worker secrets: ${WORKER_SECRETS[*]}"
